WITH exploded AS (SELECT id, service, log_ts, level, status_code, key, attr_value FROM app_logs LATERAL VIEW OUTER EXPLODE(context) x AS key, attr_value), filtered AS (SELECT *, SUBSTRING(key, 1, 4) AS key_prefix, CASE WHEN service = 'billing' THEN 1 ELSE 0 END AS is_billing FROM exploded WHERE key IS NOT NULL), valid AS (SELECT id, service, log_ts, status_code, key, attr_value, key_prefix, is_billing, TRIM(service) AS clean_service, LEAST(status_code, is_billing) AS least_status_code_is_billing FROM filtered WHERE log_ts >= TIMESTAMP '2025-06-01 06:00:00' AND key IS NOT NULL), cleaned AS (SELECT id, service, log_ts, status_code, key, attr_value, key_prefix, is_billing, clean_service, least_status_code_is_billing, is_billing * status_code AS is_billing_times_status_code, COALESCE(key, 'OTHER') AS key_filled FROM valid WHERE log_ts > TIMESTAMP '2025-06-01 13:00:00' AND least_status_code_is_billing <= 48) SELECT DATE_TRUNC('DAY', log_ts) AS activity_day, CASE WHEN status_code >= 401 THEN 'HIGH' ELSE 'LOW' END AS status_code_tier, MIN(log_ts) AS first_seen, SUM(is_billing_times_status_code) FILTER (WHERE key = 'version') AS version_total_is_billing_times_status_code, COUNT(*) AS num_rows FROM cleaned GROUP BY DATE_TRUNC('DAY', log_ts), CASE WHEN status_code >= 401 THEN 'HIGH' ELSE 'LOW' END;
